"use strict";(self.webpackChunkdocumentation_platform_docs_site=self.webpackChunkdocumentation_platform_docs_site||[]).push([["6607"],{7735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/10/29/docs-platform-launch","metadata":{"permalink":"/blog/2026/10/29/docs-platform-launch","editUrl":"https://github.com/snow-seasons-tech/documentation_platform/blog/2026-10-29-docs-platform-launch/index.mdx","source":"@site/blog/2026-10-29-docs-platform-launch/index.mdx","title":"Introducing the Snow Seasons Tech Documentation Center","description":"A new way to access our software guides and product sheets.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/blog/tags/announcement"},{"inline":true,"label":"documentation","permalink":"/blog/tags/documentation"},{"inline":true,"label":"saas","permalink":"/blog/tags/saas"}],"readingTime":0.93,"hasTruncateMarker":false,"authors":[{"name":"Snow Seasons Tech","title":"Engineering Team","url":"https://snowseasonstech.net","imageURL":"/img/logo.svg","key":"Snow Seasons Tech","page":null}],"frontMatter":{"title":"Introducing the Snow Seasons Tech Documentation Center","description":"A new way to access our software guides and product sheets.","tags":["announcement","documentation","saas"],"authors":["Snow Seasons Tech"]},"unlisted":false},"content":"We are thrilled to announce the launch of our centralized **Documentation Platform**. As we expand our suite of SaaS tools\u2014from **CDOT Stations** to **Lead Intelligence**\u2014we wanted to ensure that our customers have a world-class experience accessing the information they need.\\n\\n## What\'s New?\\n\\nOur new system isn\'t just a collection of pages; it\'s a **Docs-as-Code** pipeline. This means:\\n\\n- **Always Up-to-Date**: Documentation is generated directly from our product registries. When a feature is added to the software, it\'s added to the docs.\\n- **Professional PDFs**: Need a hard copy? Every guide now comes with a professional, branded PDF download.\\n- **Secure Access**: Via our Customer Portal, you only see the documentation for the products you are subscribed to.\\n\\n## How to get started\\n\\n1. Visit our [Documentation Center](/docs/intro).\\n2. Sign in to the [Customer Portal](https://portal.snowseasonstech.net) to access your private product sheets.\\n3. Explore the a-z of our software capabilities.\\n\\nWe are committed to transparency and clarity. If there\'s something missing from our guides, let us know through the support ticket system!\\n\\n---\\n*Published by the Snow Seasons Tech Engineering Team*"}]}}')}}]);